from engine import *
topics=[
I('project','Сайт „София“: четири страници с обща подредба',P('В този урок събираме отделните елементи в цял сайт. Темата е <strong>София</strong>. Нужни са начална страница и три вътрешни: <strong>История, География и Храмове</strong>. Всяка има собствен HTML файл.','Страниците имат четири общи части: заглавна част, навигация, основно съдържание и информация за автора и годината. Общото подреждане помага на посетителя да се ориентира, когато премине към друга страница.','Учебникът предлага готови текстове и картинки в папка website. В нашия пример необходимите имена, настройки и кратки текстове са дадени в мисията. Използваните тук изображения са отделни лицензирани илюстрации, а не файлове, които трябва вече да притежаваш.')+E('Работната папка съдържа index.html, history.html, geography.html и cathedrals.html, както и подпапка pictures за изображения. Подредбата е важна за правилните връзки.'),[('Четири страници','Начало / История / География / Храмове'),('Общи части','Заглавна част, меню, съдържание, автор'),('Работна папка','HTML файлове + pictures')],C('Кои решения отговарят на проекта?',['Начална страница и три вътрешни.','Отделен HTML файл за всяка страница.','Обща навигация.','Изтриване на всички връзки във вътрешните страници.','Подредена папка за изображенията.','Единствено една снимка без никакво съдържание или структура.'],[0,1,2,4],'Проектът съчетава четири свързани страници, обща структура и подредени ресурси. Самата снимка не изгражда целия сайт.')),
I('home','Подготвяме началната страница',P('В готовия пример в Composer е отворена празна страница и е записана като <strong>index.html</strong>. Името позволява началната страница да бъде разпознавана лесно, а записването в общата работна папка пази относителните пътища подредени.','В <strong>Format → Page Title and Properties</strong> са зададени Title „София“, Author „Учебен екип“ и кратко Description „История, география и храмове на София“. Полето за описание е смислен текст за съдържанието, а не произволни повторения.','В <strong>Format → Page Colors and Background</strong> са избрани четим фон и цветове на връзките. В задачата цветовете на обикновена, активна и посетена връзка са еднакви; в нашия пример връзките остават разпознаваеми чрез ясния надпис и подчертаване.','При преглед с Preview или Browse първо се записват промените, за да се гледа актуалната версия.')+E('Резултатът е подготвен местен файл с общите свойства. Той още не е автоматично публикуван в интернет.'),[('Файл','index.html'),('Title / Author','София / Учебен екип'),('Save → Preview / Browse','Преглед на актуалните промени')],C('Кои действия са част от примера?',['Записване като index.html.','Задаване на Title и описание.','Избор на четим фон и разпознаваеми връзки.','Приемане, че Save автоматично публикува в интернет.','Записване преди преглед в браузъра.','Използване на Description само като място за произволни несвързани думи.'],[0,1,2,4],'Записването и общите свойства подготвят страницата. Прегледът трябва да използва актуалното копие; публикацията е отделно действие.')),
I('layout','Таблицата подрежда общия изглед',P('Условието използва таблица с <strong>2 реда и 3 колони</strong>, общо 6 клетки. Ширината е <strong>1000 пиксела</strong>, без видима рамка. Това е зададената учебна подредба, а не универсално решение за всички съвременни екрани.','В Table Properties са избрани центриране, сив фон, <strong>Spacing 10</strong> и <strong>Padding 5</strong>. Първото е разстояние между клетките, второто — място между текста и ръба на клетката.','Първият ред е висок <strong>150 пиксела</strong>. Първата и третата колона са широки по <strong>200 пиксела</strong>. Средната част е за основното заглавие и текст; действителното ѝ пространство зависи и от разстоянията. Вторият ред трябва да побира своето съдържание.')+E('Фиксираната ширина е прегледана и в тесен прозорец. Ако не се събира, това е ограничение на примера. Съвременен адаптивен сайт обикновено използва CSS за подредбата и приспособяването.'),[('Размер','2 реда × 3 колони; ширина 1000 px'),('Разстояния','Spacing 10; Padding 5; Border 0'),('Горна част','Височина 150 px; крайни колони по 200 px')],C('Кои настройки са разтълкувани правилно?',['2 × 3 означава шест клетки.','Border 0 означава без видима рамка.','Spacing 10 е място между клетките.','Padding 5 е място между текста и ръба.','1000 пиксела гарантира удобно събиране на всеки телефон.','200 пиксела означава двеста отделни вътрешни страници.'],[0,1,2,3],'Числата описват конкретната таблица и разстоянията. Фиксираната ширина не гарантира удобство при всеки екран.')),
I('header','Заглавната част остава еднаква',F('arms','Гербът на София — пример за изображение в заглавната част.')+F('statue','Статуята на София — изображение за представяне на града.')+P('Първият ред служи като обща заглавна част на четирите страници. В първата клетка в примера се поставя изображение на герба, в средната — <strong>СОФИЯ</strong> и девизът <strong>„Расте, но не старее“</strong>, а в третата — изображение на статуята на София.','В материалите от учебника тези файлове са наречени gerb.png и sv_sofia.png. Важна е връзката между избрания графичен файл и мястото му в страницата, а не самото име. Чрез Insert → Image се посочва съответният файл и се дава смислен алтернативен текст.','В Cells текстът и изображенията са центрирани по хоризонтала и вертикала. Размерите са съобразени с клетките, а пропорциите на изображенията са запазени. Заглавната част не се измисля наново на всяка страница.')+E('Когато посетителят отиде от Начало към История, същата горна част му показва, че още е в сайта „София“.'),[('Лява клетка','Герб'),('Средна клетка','СОФИЯ; „Расте, но не старее“'),('Дясна клетка','Изображение на статуята')],C('Кои решения са правилни?',['Общата заглавна част е еднаква на страниците.','Изображенията се вмъкват като файлове с правилен път.','Даваме смислен алтернативен текст.','Изображенията задължително се разтягат непропорционално, за да запълнят всяко пространство.','Центрирането може да бъде и хоризонтално, и вертикално.','Смяната на страница изисква непременно нов несвързан герб.'],[0,1,2,4],'Последователният изглед, правилните пътища и пропорционалните изображения правят заглавната част разпознаваема.')),
I('home-content','Меню, основен текст и допълнителни връзки',P('Във втория ред на таблицата лявата клетка съдържа меню: <strong>Начало, История, География, Храмове</strong>. Средната клетка е за основния текст и изображение. В дясната се поставят допълнителни външни връзки, например към Столична община и страница за София в енциклопедия.','В готовия пример основният текст започва: „София е столицата на България. Сайтът представя накратко историята, географското положение и някои храмове на града.“ Това е собствен кратък учебен текст, който заменя зависимостта от липсващия index.doc.','Под основното съдържание е поставена информация за учебния автор и годината. Менюто се отделя визуално от текста, за да не се търсят връзките между абзаците.')+E('Ако посетителят иска история, избира История в лявото меню. Ако иска официална общинска информация, използва външната връзка. Двете посоки имат различна цел.'),[('Лява клетка','Основно меню'),('Средна клетка','Представяне, текст и изображение'),('Дясна / долна част','Допълнителни връзки / автор и година')],C('Кои елементи са поставени според плана?',['Основното меню в лявата част.','Основният текст в централната част.','Допълнителни външни връзки отделно от менюто.','Всички връзки скрити без надписи.','Автор и година в допълнителната долна част.','Основният текст е заменен единствено с името на инсталационния файл.'],[0,1,2,4],'Подредбата разделя навигация, съдържание и допълнителна информация. Ясните надписи помагат да се избере правилната посока.')),
I('inner-pages','Създаваме вътрешните страници',P('След началната страница са подготвени <strong>history.html</strong>, <strong>geography.html</strong> и <strong>cathedrals.html</strong>. В примера имената са на латиница и са точно еднакви навсякъде, където се използват.','За общата подредба е отворен index.html. Чрез <strong>Table → Select → Table</strong> таблицата е избрана и копирана в новата страница. Общата заглавна част и менюто остават; основният текст и снимката се сменят според темата.','Title също се променя: „София — история“, „София — география“ или „София — храмове“. Копирането не бива да остави навсякъде едно и също заглавие и съдържание. След редакцията всеки файл се записва отделно.')+T(['Файл','Собствено съдържание'],[['history.html','Историческо представяне; например антична Сердика.'],['geography.html','Софийското поле и близостта до Витоша.'],['cathedrals.html','Кратко представяне на храмове.']]),[('Копираме','Общата структура'),('Сменяме','Title, основен текст и изображение'),('Пазим','Три отделни вътрешни HTML файла')],C('Кои действия са правилни?',['Запазваме отделен файл за всяка тема.','Копираме общото оформление.','Променяме основния текст и Title.','Оставяме всички страници с еднакъв случаен текст независимо от темата.','Използваме еднакви точни имена в файловете и връзките.','Изтриваме менюто само от вътрешните страници.'],[0,1,2,4],'Копирането пази общата структура, но тематичното съдържание и заглавието трябва да се обновят. Имената трябва да съвпадат с връзките.')),
I('text-image','Текстът и снимката работят заедно',F('cathedral','Храм „Свети Александър Невски“ — пример за съдържание на страницата „Храмове“.')+P('В страницата за историята учебникът използва текст от history.doc и изображение serdica.png. В готовия пример описваме антична Сердика и показваме къде би стояла подходяща снимка. Двете трябва да се отнасят за една и съща тема.','В <strong>Image Properties → Appearance</strong> е избрано <strong>Wrap to the left</strong>: текстът се разполага отляво на изображението. Около снимката са оставени <strong>5 пиксела</strong>, без рамка. Това разстояние пази буквите от залепване за ръба.','По същия начин се оформят географията и храмовете с подходящи собствени текстове и изображения. Шрифтът, цветовете и основните размери остават последователни. Допълнителен материал се включва след проверка на точността и правото за използване.')+E('За Храмове е подходяща снимка на храм, а не произволна графика от друга тема. Връзката между текст и изображение е по-важна от броя снимки.'),[('История','Свързан текст и изображение за Сердика'),('Wrap to the left','Текст отляво на изображението'),('Appearance','Разстояние 5 px; без рамка')],C('Кои решения отговарят на примера?',['Изображението е свързано с темата на текста.','Оставя се разстояние до буквите.','Общият стил се пази между страниците.','Произволна несвързана снимка винаги е по-полезна от подходяща.','Проверяват се допълнителните материали.','Wrap to the left означава деинсталиране на редактора.'],[0,1,2,4],'Видът и съдържанието трябва да се подкрепят. Разстоянието и стилът улесняват четенето; командата определя разположението, а не инсталирането.')),
I('internal-links','Свързваме вътрешните страници',P('В страницата index.html текстът <strong>История</strong> е маркиран и чрез <strong>Insert → Link</strong> е отворен Link Properties. С Choose File е избран <strong>history.html</strong>, след което изборът е потвърден.','Същото е направено за География → geography.html и Храмове → cathedrals.html. Начало води към index.html. Това са връзки между файловете в общата работна папка. Те не трябва да сочат към чужда случайна папка само на компютъра на автора.','Менюто е поставено и проверено във всяка от четирите страници. Когато от История изберем Храмове, трябва да се отвори правилният тематичен файл; връщането към Начало също трябва да работи.')+T(['Видим надпис','Цел'],[['Начало','index.html'],['История','history.html'],['География','geography.html'],['Храмове','cathedrals.html']])+E('Надписът и целта са различни неща. Красивият надпис не поправя грешен адрес, затова проверяваме с реално отваряне след запис.'),[('История','history.html'),('География / Храмове','geography.html / cathedrals.html'),('Проверка','Всички връзки от всяка страница')],C('Кои връзки са правилни за проекта?',['Начало → index.html.','История → history.html.','География → geography.html.','Храмове → случайния инсталационен файл.','Храмове → cathedrals.html.','Менюто трябва да работи само на началната страница.'],[0,1,2,4],'Всяка връзка трябва да води към конкретния тематичен файл. Менюто е необходимо и във вътрешните страници.')),
I('external-links','Външни връзки и цялостна проверка',P('За <strong>Столична община</strong> в готовия пример е използван официалният адрес <strong>https://www.sofia.bg/</strong>. При външна връзка в Link Location се задава пълният уеб адрес. Връзката към енциклопедична страница за София има друг адрес и друга цел.','Адресът се взема от действителната страница, а не се измисля по надписа. Външният сайт може да се променя, затова връзките се проверяват и при поддръжката. За вътрешните връзки се проверяват нашите четири файла.','В края е прегледан целият проект: заглавия, меню, изображения, автор, година, фон и четимост. Отворени са всички връзки, а изображение с липсващ път е поправено. Само началната страница не е достатъчна проверка.')+E('Готов резултат: четири подредени и свързани местни страници. Това е учебният сайт за преглед; публикуването в интернет е отделна следваща дейност.'),[('Вътрешна връзка','history.html — наш файл'),('Външна връзка','https://www.sofia.bg/ — друг сайт'),('Проверка','Четири страници, изображения и всички връзки')],C('Кои проверки са подходящи?',['Пълният адрес на външната връзка.','Отварянето на всички вътрешни страници.','Зареждането на изображенията.','Само цветът на началната страница.','Съответствието между надпис и цел.','Приемане, че всеки местен файл вече е публикуван.'],[0,1,2,4],'Проверяваме адреси, съдържание и ресурси в целия проект. Местният работещ сайт още не е непременно публичен.')),
I('personal','Прилагаме общия план към друга тема',P('Заключителната задача предлага личен сайт или тема по избор. Подходът не се променя само защото вместо София представяме училищен клуб. Първо избираме целта и нужните страници, после обща подредба и свързано съдържание.','В готовия нов план темата е „Клуб по рисуване“. Началната страница представя клуба. Вътрешните страници са Дейности, Галерия и Контакти. Общата заглавна част и менюто остават на всички страници, а текстът и снимките са за конкретната тема.','Шаблонът може да даде начало, но не замества проверката. Нужни са собствени заглавия, подходящи изображения, правилни връзки и четимост. Празните примерни надписи от шаблона се заменят със смислено съдържание.')+E('Така от готовата схема за четири страници се получава нов последователен план, без да се копират несвързани сведения за София.'),[('Нова тема','Клуб по рисуване'),('Страници','Начало, Дейности, Галерия, Контакти'),('Пазим подхода','Общ вид + собствено съдържание + проверени връзки')],O('Как би приспособил общата структура за сайта „Клуб по рисуване“?','Опиши един свързан план в 4–6 изречения със свои думи и дай пример за вътрешна връзка.','Началната страница представя клуба по рисуване. Добавям вътрешни страници Дейности, Галерия и Контакти. Всички използват една заглавна част и едно меню, но имат собствен текст и подходящи снимки. Например връзката „Галерия“ води към gallery.html. Накрая проверявам връзките и изображенията във всяка страница. За самопроверка: включи общ вид, собствено съдържание и пример за правилна връзка; възможни са и други обосновани планове.'))]
build(19,'website-components','Създаване и интегриране на компонентите на сайт','54–56',P('Ще проследиш цялостен сайт „София“ от четири страници. Общите части ще се запазят, а основният текст и снимките ще се сменят според темата.','Ще видиш конкретните настройки от учебника, готовите имена на файлове и начина за свързването им. Не е необходимо да разполагаш с файловете от учебното приложение или да инсталираш Composer, за да преминеш мисията.'),topics,['<strong>Четирите страници имат обща заглавна част и меню.</strong>','<strong>Всяка тема има собствен файл, заглавие, текст и изображения.</strong>','<strong>Таблицата от примера подрежда елементите чрез конкретни размери и разстояния.</strong>','<strong>Вътрешната връзка води към наш файл, външната — към друг уеб адрес.</strong>','<strong>Проверяваме всички страници и ресурси, преди да смятаме проекта за готов.</strong>'],['Стр.54: проектСофия/4страници/4части; папкаwebsite; index/Title/Author/Description/цветове/Preview/Browse; Table2×3/1000px/Border0/Spacing10/Padding5/Center/сивфон/150px/200px.','Стр.55: герб/заглавие/девиз/статуя/центриране; меню/основентекст/изображение/външнивръзки/автор/година.','Стр.56: вътрешни файлове geography/history/cathedrals; копиране на таблица; тематични текстове; Serdica/WrapLeft/5px/Border0; вътрешни и външни връзки; личен тематичен сайт.'],[('SeaMonkey: помощ','https://www.seamonkey-project.org/doc/'),('Столична община','https://www.sofia.bg/'),('Wikimedia: изображенията','https://commons.wikimedia.org/')], 'Изображенията и задължителните лицензи са в authoring/it8-textbook-batch/sofia-images.json. Собствените кратки текстове заменят недостъпните издателски DOC ресурси. Поправен е грешният път до Page Colors в източника. Фиксираната таблица е учебен исторически подход, не обещание за адаптивност. Няма автоматично добавена връзка от HTML урок към мисия.')
